// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MergingPool} from "../src/MergingPool.sol";

contract InvMutTest is Test {
    MergingPool c;
    function setUp() public { c = new MergingPool(address(this), address(this), address(new __InvMutHandleStub())); }

    function testFuzz_property(uint256 newWinnersPerPeriodAmount) public {
        // The admin (this contract) updates winnersPerPeriod to any value.
        c.updateWinnersPerPeriod(newWinnersPerPeriodAmount);

        // General rule: after a successful call updateWinnersPerPeriod(v),
        // c.winnersPerPeriod() must equal v for EVERY admissible input v.
        assertTrue(c.winnersPerPeriod() == newWinnersPerPeriodAmount);
    }
}
